function db(){static $pdo;global $config;if(!$pdo){if(!is_dir(__DIR__.'/data'))mkdir(__DIR__.'/data',0755,true);$pdo=new PDO('sqlite:'.$config['storage']);$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$pdo->exec('PRAGMA foreign_keys=ON');$pdo->exec('CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,user_id TEXT UNIQUE,password_hash TEXT NOT NULL,totp_secret TEXT NOT NULL,wallet_address TEXT NOT NULL,balance_sat INTEGER NOT NULL DEFAULT 0,demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL)');$pdo->exec('CREATE TABLE IF NOT EXISTS txs(id INTEGER PRIMARY KEY,type TEXT NOT NULL,status TEXT NOT NULL,from_user TEXT,to_user TEXT,amount_sat INTEGER NOT NULL DEFAULT 0,fee_sat INTEGER NOT NULL DEFAULT 0,txid TEXT,details TEXT,created_at TEXT NOT NULL)');$pdo->exec('CREATE TABLE IF NOT EXISTS attempts(id INTEGER PRIMARY KEY,ip TEXT NOT NULL,created_at INTEGER NOT NULL)');}return $pdo;}
function e($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}function now(){return gmdate('c');}function p($k,$d=''){return trim((string)($_POST[$k]??$d));}function is_demo(){global $config;return $config['mode']==='demo';}function csrf(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}function token(){echo '<input type="hidden" name="csrf" value="'.e(csrf()).'">';}function check(){if($_SERVER['REQUEST_METHOD']==='POST'&&!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(400);exit('bad token');}}
function satbtc($s){return number_format(((int)$s)/100000000,8,'.','');}function btcsat($b){return (int)round(((float)$b)*100000000);}function price_usd(){global $config;$f=$config['price_cache'];$c=is_file($f)?json_decode(file_get_contents($f),true):null;if(is_array($c)&&isset($c['usd'],$c['time'])&&time()-$c['time']<120)return (float)$c['usd'];$raw=@file_get_contents('https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd',false,stream_context_create(['http'=>['timeout'=>4,'header'=>'Accept: application/json\r\n']]));$usd=0;if($raw){$j=json_decode($raw,true);$usd=(float)($j['bitcoin']['usd']??0);}if($usd>0){file_put_contents($f,json_encode(['usd'=>$usd,'time'=>time()],JSON_PRETTY_PRINT),LOCK_EX);return $usd;}return is_array($c)&&isset($c['usd'])?(float)$c['usd']:0;}function usd_sat($usd){$p=price_usd();return $p>0?(int)round(((float)$usd/$p)*100000000):0;}function satusd($s){$p=price_usd();return $p>0?(((int)$s)/100000000)*$p:0;}function usd($n){return number_format((float)$n,2,'.',',');}
function btc_ok($a){return preg_match('/^(bc1|tb1|bcrt1|[13mn2])[a-zA-HJ-NP-Z0-9]{25,90}$/',$a);}function txid_ok($v){return $v===''||preg_match('/^[a-fA-F0-9]{64}$/',$v);}function uid(){return 'DM-'.strtoupper(bin2hex(random_bytes(4)));}
function total_sat(){return (int)db()->query('SELECT COALESCE(SUM(balance_sat),0) FROM users')->fetchColumn();}function share($s){$t=total_sat();return $t>0?($s/$t*100):0;}function addtx($type,$status,$from,$to,$amt,$fee,$txid,$details){$q=db()->prepare('INSERT INTO txs(type,status,from_user,to_user,amount_sat,fee_sat,txid,details,created_at) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$type,$status,$from,$to,$amt,$fee,$txid,$details,now()]);}
function log_json($ev){global $config;$f=$config['event_log'];$a=is_file($f)?json_decode(file_get_contents($f),true):[];if(!is_array($a))$a=[];$a[]=array_merge(['time'=>now()],$ev);file_put_contents($f,json_encode($a,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);}
function b32e($d){$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';$o='';for($i=0;$i<strlen($d);$i++)$bits.=str_pad(decbin(ord($d[$i])),8,'0',STR_PAD_LEFT);foreach(str_split($bits,5) as $c){if(strlen($c)<5)$c=str_pad($c,5,'0');$o.=$a[bindec($c)];}return $o;}function b32d($b){$a='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$b=strtoupper(preg_replace('/[^A-Z2-7]/','',$b));$bits='';$o='';for($i=0;$i<strlen($b);$i++){ $v=strpos($a,$b[$i]);if($v!==false)$bits.=str_pad(decbin($v),5,'0',STR_PAD_LEFT);}foreach(str_split($bits,8) as $c)if(strlen($c)===8)$o.=chr(bindec($c));return $o;}function secret(){return b32e(random_bytes(20));}function totp($sec,$time=null){$time=$time??time();$ctr=floor($time/30);$h=hash_hmac('sha1',pack('N*',0).pack('N*',$ctr),b32d($sec),true);$o=ord(substr($h,-1))&15;$v=((ord($h[$o])&127)<<24)|(ord($h[$o+1])<<16)|(ord($h[$o+2])<<8)|ord($h[$o+3]);return str_pad($v%1000000,6,'0',STR_PAD_LEFT);}function ok_totp($sec,$c){$c=preg_replace('/\D/','',$c);for($i=-1;$i<=1;$i++)if(hash_equals(totp($sec,time()+$i*30),$c))return true;return false;}
function current_user(){if(is_demo()&&!empty($_SESSION['demo_uid'])){$s=db()->prepare('SELECT * FROM users WHERE user_id=? AND demo=1');$s->execute([$_SESSION['demo_uid']]);return $s->fetch(PDO::FETCH_ASSOC)?:null;}if(empty($_SESSION['uid']))return null;$s=db()->prepare('SELECT * FROM users WHERE user_id=?');$s->execute([$_SESSION['uid']]);return $s->fetch(PDO::FETCH_ASSOC)?:null;}function need_user(){if(!current_user()){header('Location:?p=login');exit;}}
